import { randomUUID } from "node:crypto";

import type { SignedKeyPairResponse } from "@netrics/contracts";
import {
  consumePendingKey,
  countActivePendingKeys,
  findPendingKey,
  insertPendingKey,
  withWorkspace,
  type Database,
  type PendingKeyOwner,
  type Transaction,
} from "@netrics/database";

import {
  decryptPendingSignedKey,
  encryptPendingSignedKey,
  type CredentialKeyring,
} from "../credentials.js";
import { generateP256KeyPair } from "./keys.js";
import type { SignedKeyProviderDefinition } from "./providers/index.js";

// Key pairs generated by netrics (ADR 0020 §3, #371). The host generates an
// EC P-256 pair; the public key goes to the user, who pastes it at the
// provider, and the private key waits as a pending key: sealed in an
// AES-GCM envelope bound to its row, readable only by the user who
// generated it, in its workspace, for 24 hours. A connection created (or a
// key replaced) with its id takes the key into the connection's envelope
// and deletes the row in the same commit. The private key is never in a
// response, a log line or an error.

/** How long a generated key waits for its connection. */
export const PENDING_KEY_LIFETIME_MS = 24 * 60 * 60 * 1000;

/**
 * Unexpired pending keys per user and workspace. Each one is a row with a
 * sealed private key; a user setting up a few accounts needs a handful.
 */
export const MAX_ACTIVE_PENDING_KEYS = 20;

/** What the user reads when a pending key cannot be used. */
export const PENDING_KEY_UNUSABLE =
  "The generated key pair is no longer available: it expired after 24 hours, was already used for a connection, or was generated by someone else. Generate a new key pair and paste its public key again.";

export type GenerateKeyPairResult =
  | { ok: true; value: SignedKeyPairResponse }
  | { ok: false; status: 400; error: string };

export interface PendingKeyStoreDeps {
  db: Database;
  credentialKeyring: CredentialKeyring;
  /** Clock (ms since epoch); tests pin it. */
  now?: () => number;
}

export function createPendingKeyStore(deps: PendingKeyStoreDeps) {
  const { db, credentialKeyring } = deps;
  const now = () => new Date((deps.now ?? Date.now)());
  const inWorkspace = <T>(
    owner: PendingKeyOwner,
    run: (tx: Transaction) => Promise<T>,
  ) =>
    withWorkspace(
      db,
      { workspaceId: owner.workspaceId, userId: owner.userId },
      run,
    );

  return {
    /**
     * Generates a key pair for `provider` and stores its private key as a
     * pending key of `owner`. Only providers with `generatedKeyPair` do.
     */
    async generate(
      owner: PendingKeyOwner,
      provider: SignedKeyProviderDefinition,
    ): Promise<GenerateKeyPairResult> {
      if (!provider.generatedKeyPair) {
        return {
          ok: false,
          status: 400,
          error: `${provider.name} gives you its key; netrics does not generate one for it.`,
        };
      }
      const at = now();
      return inWorkspace(owner, async (tx) => {
        const active = await countActivePendingKeys(tx, owner, at);
        if (active >= MAX_ACTIVE_PENDING_KEYS) {
          return {
            ok: false,
            status: 400,
            error: `You have ${MAX_ACTIVE_PENDING_KEYS} generated key pairs that are not used yet. Use one, or wait until they expire after 24 hours.`,
          };
        }
        const pair = generateP256KeyPair();
        const id = randomUUID();
        const expiresAt = new Date(at.getTime() + PENDING_KEY_LIFETIME_MS);
        await insertPendingKey(tx, {
          ...owner,
          id,
          provider: provider.id,
          privateKeyEncrypted: Buffer.from(
            encryptPendingSignedKey(pair.privateKeyPem, credentialKeyring, {
              workspaceId: owner.workspaceId,
              pendingKeyId: id,
            }),
            "utf8",
          ),
          expiresAt,
        });
        return {
          ok: true,
          value: {
            pendingKeyId: id,
            publicKey: pair.publicKeyPem,
            expiresAt: expiresAt.toISOString(),
          },
        };
      });
    },

    /**
     * The private key PEM of the owner's unexpired pending key of
     * `providerId`, or null (another workspace's, another user's, another
     * provider's, expired, used, or its envelope does not open). It does
     * not consume the key; `consume` does, in the storing transaction.
     */
    async privateKey(
      owner: PendingKeyOwner,
      providerId: string,
      pendingKeyId: string,
    ): Promise<string | null> {
      const row = await inWorkspace(owner, (tx) =>
        findPendingKey(tx, owner, pendingKeyId, providerId, now()),
      );
      if (!row) {
        return null;
      }
      try {
        return decryptPendingSignedKey(
          row.privateKeyEncrypted.toString("utf8"),
          credentialKeyring,
          { workspaceId: owner.workspaceId, pendingKeyId: row.id },
        );
      } catch {
        return null;
      }
    },

    /**
     * Deletes the pending key inside the transaction that stores it in a
     * connection's envelope. False when it is gone (a concurrent request
     * used it, or it expired meanwhile): the caller stores nothing.
     */
    consume(
      tx: Transaction,
      owner: PendingKeyOwner,
      providerId: string,
      pendingKeyId: string,
    ): Promise<boolean> {
      return consumePendingKey(tx, owner, pendingKeyId, providerId, now());
    },
  };
}

export type PendingKeyStore = ReturnType<typeof createPendingKeyStore>;
